from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.webdriver.support import expected_conditions as EC
from selenium.common.exceptions import JavascriptException, TimeoutException
from taf.selenium.core.common import PagePart
from taf.selenium.sc.common.utils import choose_selector_way


class LocalBasicPage(PagePart):
    """
    Basic class, initializes web driver and provides common element operations functions.
    """

    def __init__(self, webdriver, download_checker=None, screenshot_dir=None):
        super(LocalBasicPage, self).__init__(webdriver)
        self._download_checker = download_checker
        self._default_screenshot_dir = screenshot_dir

    @property
    def download_checker(self):
        return self._download_checker

    @property
    def driver(self):
        return self._driver

    @property
    def download_dir(self):
        return self._download_checker.download_dir if self._download_checker else None

    @property
    def downloader(self):
        return self._download_checker.downloader if self._download_checker else None

    def save_screenshot(self, filename):
        return super(LocalBasicPage, self).save_screenshot(filename, self._default_screenshot_dir)

    def download_files(self, start_time, download_timeout=1800):
        return self._download_checker.check(start_time, download_timeout)

    def click_enabled_element_after_visible(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)
        self.click_enabled_element(locator, timeout)

    @choose_selector_way
    def hide_element(self, select_element_script, *args, **kwargs):
        self._driver.execute_script(''.join([select_element_script, ".style=''"]))

    @choose_selector_way
    def display_element_in_sc(self, select_element_script, *args, **kwargs):
        self._driver.execute_script(''.join([select_element_script, ".style.display='inline-block'"]))
        self._driver.execute_script(''.join([select_element_script, ".style.opacity=1"]))
        self._driver.execute_script(''.join([select_element_script, ".style.fontSize='5px'"]))

    def load_file_from_hidden_button(self, button_location, button_xpath, file_path, timeout=10):
        """
        Actual load file button is hidden normally by developer, so we should show it , load file and then hide it

        :param button_location: str, hidden button unique location in web element
        :param button_xpath: str, hidden button's xpath
        :param file_path: str, load file's directory
        :param timeout: int, time to wait file loading, default 10 seconds.

        :return:
        """
        self.display_element_in_sc(button_location, by="id")
        self._wait_for_element_by((By.XPATH, button_xpath), timeout)
        elem = self._driver.find_element_by_xpath(button_xpath)
        self._driver.execute_script("arguments[0].scrollIntoView();", elem)
        elem.clear()
        elem.send_keys(file_path)
        try:
            self.hide_element(button_location, by="id")
        except JavascriptException:
            pass

    def wait_until_element_is_clickable(self, xpath, timeout):
        try:
            self._until(EC.element_to_be_clickable((By.XPATH, xpath)), timeout)
        except TimeoutException:
            msg = 'Element with given xpath: {0} has not been able to click'.format(xpath)
            raise TimeoutException(msg)

    def fetch_element_until_is_clickable(self, xpath, timeout):
        self.wait_until_element_is_clickable(xpath, timeout)
        return self._driver.find_element_by_xpath(xpath)

    def fetch_element_until_is_visible(self, locator, timeout=10):
        self.wait_for_visibility(locator, timeout)
        return self._driver.find_element(*locator)
